1	//! Raw blob hashing and the product H preimage; neither implies admission.
2	use crate::canonical::{self, Value};
3	use alloc::{string::String, vec::Vec};
4	use core::fmt::{self, Write};
5	use sha2_const_stable::Sha256;
6	
7	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
8	pub enum Error {
9	    Domain,
10	    Canonical(canonical::Error),
11	}
12	
13	impl fmt::Display for Error {
14	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
15	        match self {
16	            Self::Domain => f.write_str("invalid hash domain"),
17	            Self::Canonical(error) => write!(f, "canonical encoding failed: {error}"),
18	        }
19	    }
20	}
21	
22	impl core::error::Error for Error {
23	    fn source(&self) -> Option<&(dyn core::error::Error + 'static)> {
24	        match self {
25	            Self::Canonical(error) => Some(error),
26	            Self::Domain => None,
27	        }
28	    }
29	}
30	
31	pub fn raw_sha256(bytes: &[u8]) -> [u8; 32] {
32	    Sha256::new().update(bytes).finalize()
33	}
34	
35	pub fn hex(digest: &[u8; 32]) -> String {
36	    let mut value = String::with_capacity(64);
37	    for byte in digest {
38	        write!(value, "{byte:02x}").expect("writing to String cannot fail");
39	    }
40	    value
41	}
42	
43	/// Complete H preimage. Callers must separately admit the registered descriptor.
44	pub fn frame(domain: &str, value: &Value) -> Result<Vec<u8>, Error> {
45	    if domain.is_empty()
46	        || !domain
47	            .bytes()
48	            .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || matches!(b, b'-' | b'.'))
49	    {
50	        return Err(Error::Domain);
51	    }
52	    let canonical = canonical::encode(value).map_err(Error::Canonical)?;
53	    let mut frame = Vec::new();
54	    frame.extend_from_slice(b"opensip.product.v1\0");
55	    frame.extend_from_slice(domain.as_bytes());
56	    frame.push(0);
57	    frame.extend_from_slice(&(canonical.len() as u64).to_be_bytes());
58	    frame.extend_from_slice(&canonical);
59	    Ok(frame)
60	}
61	
62	pub fn identity(domain: &str, value: &Value) -> Result<[u8; 32], Error> {
63	    Ok(raw_sha256(&frame(domain, value)?))
64	}
