1	use crate::{
2	    constants::{K256, K512},
3	    util::{load_u32_be, load_u64_be, memcpy, memset, store_u128_be, store_u32_be, store_u64_be},
4	};
5	use core::mem;
6	
7	macro_rules! sha {
8	    (
9	        $name:ident,
10	        $word:ty,
11	        $load_word:ident,
12	        $store_word:ident,
13	        $k:ident,
14	        $length:ty,
15	        $store_length:ident,
16	        $bsig0:tt,
17	        $bsig1:tt,
18	        $ssig0:tt,
19	        $ssig1:tt
20	    ) => {
21	        #[derive(Clone)]
22	        pub(crate) struct $name {
23	            state: [$word; 8],
24	            buffer: [u8; 16 * mem::size_of::<$word>()],
25	            offset: usize,
26	            length: $length,
27	        }
28	
29	        impl $name {
30	            /// The internal block size of the hash function.
31	            pub(crate) const BLOCK_SIZE: usize = 16 * Self::WORD_SIZE;
32	            const DIGEST_SIZE: usize = 8 * Self::WORD_SIZE;
33	            const LENGTH_OFFSET: usize = Self::BLOCK_SIZE - Self::LENGTH_SIZE;
34	            const LENGTH_SIZE: usize = mem::size_of::<$length>();
35	            const WORD_SIZE: usize = mem::size_of::<$word>();
36	
37	            /// Construct a new instance.
38	            pub(crate) const fn new(state: [$word; 8]) -> Self {
39	                Self {
40	                    state,
41	                    buffer: [0; Self::BLOCK_SIZE],
42	                    offset: 0,
43	                    length: 0,
44	                }
45	            }
46	
47	            /// Add input data to the hash context.
48	            pub(crate) const fn update(mut self, input: &[u8]) -> Self {
49	                let offset = self.offset;
50	                let needed = Self::BLOCK_SIZE - offset;
51	
52	                if needed > input.len() {
53	                    self.buffer = memcpy(self.buffer, offset, input, 0, input.len());
54	                    self.offset += input.len();
55	                } else {
56	                    self.buffer = memcpy(self.buffer, offset, input, 0, needed);
57	                    self.state = Self::compress(self.state, &self.buffer, 0);
58	
59	                    let mut i = needed;
60	                    loop {
61	                        let remain = input.len() - i;
62	                        if remain < Self::BLOCK_SIZE {
63	                            self.buffer = memcpy(self.buffer, 0, input, i, remain);
64	                            self.offset = remain;
65	                            break;
66	                        } else {
67	                            self.state = Self::compress(self.state, input, i);
68	                            i += Self::BLOCK_SIZE;
69	                        }
70	                    }
71	                }
72	
73	                self.length += (input.len() as $length) * 8;
74	                self
75	            }
76	
77	            pub(crate) const fn finalize(mut self) -> [u8; Self::DIGEST_SIZE] {
78	                let mut offset = self.offset;
79	                self.buffer[offset] = 0x80;
80	                offset += 1;
81	
82	                if offset > Self::LENGTH_OFFSET {
83	                    self.buffer = memset(self.buffer, offset, 0, Self::BLOCK_SIZE - offset);
84	                    self.state = Self::compress(self.state, &self.buffer, 0);
85	                    offset = 0;
86	                }
87	
88	                self.buffer = memset(self.buffer, offset, 0, Self::LENGTH_OFFSET - offset);
89	                self.buffer = $store_length(self.buffer, Self::LENGTH_OFFSET, self.length);
90	                self.state = Self::compress(self.state, &self.buffer, 0);
91	
92	                let mut digest = [0; Self::DIGEST_SIZE];
93	                let mut i = 0;
94	                while i < self.state.len() {
95	                    digest = $store_word(digest, i * Self::WORD_SIZE, self.state[i]);
96	                    i += 1
97	                }
98	
99	                digest
100	            }
101	
102	            /// SHA compression function.
103	            ///
104	            /// This function takes an `offset` because subslices are not supported in
105	            /// `const fn`.
106	            const fn compress(mut state: [$word; 8], buffer: &[u8], offset: usize) -> [$word; 8] {
107	                #[inline(always)]
108	                const fn ch(x: $word, y: $word, z: $word) -> $word {
109	                    (x & y) ^ ((!x) & z)
110	                }
111	                #[inline(always)]
112	                const fn maj(x: $word, y: $word, z: $word) -> $word {
113	                    (x & y) ^ (x & z) ^ (y & z)
114	                }
115	                #[inline(always)]
116	                const fn big_sigma0(x: $word) -> $word {
117	                    x.rotate_right($bsig0.0) ^ x.rotate_right($bsig0.1) ^ x.rotate_right($bsig0.2)
118	                }
119	                #[inline(always)]
120	                const fn big_sigma1(x: $word) -> $word {
121	                    x.rotate_right($bsig1.0) ^ x.rotate_right($bsig1.1) ^ x.rotate_right($bsig1.2)
122	                }
123	                #[inline(always)]
124	                const fn sigma0(x: $word) -> $word {
125	                    x.rotate_right($ssig0.0) ^ x.rotate_right($ssig0.1) ^ (x >> $ssig0.2)
126	                }
127	                #[inline(always)]
128	                const fn sigma1(x: $word) -> $word {
129	                    x.rotate_right($ssig1.0) ^ x.rotate_right($ssig1.1) ^ (x >> $ssig1.2)
130	                }
131	
132	                let mut w: [$word; $k.len()] = [0; $k.len()];
133	
134	                let mut i = 0;
135	                while i < 16 {
136	                    w[i] = $load_word(buffer, offset + i * mem::size_of::<$word>());
137	                    i += 1;
138	                }
139	                while i < $k.len() {
140	                    w[i] = sigma1(w[i - 2])
141	                        .wrapping_add(w[i - 7])
142	                        .wrapping_add(sigma0(w[i - 15]))
143	                        .wrapping_add(w[i - 16]);
144	                    i += 1;
145	                }
146	
147	                let mut a = state[0];
148	                let mut b = state[1];
149	                let mut c = state[2];
150	                let mut d = state[3];
151	                let mut e = state[4];
152	                let mut f = state[5];
153	                let mut g = state[6];
154	                let mut h = state[7];
155	
156	                let mut i = 0;
157	                while i < $k.len() {
158	                    let t1 = h
159	                        .wrapping_add(big_sigma1(e))
160	                        .wrapping_add(ch(e, f, g))
161	                        .wrapping_add($k[i])
162	                        .wrapping_add(w[i]);
163	                    let t2 = big_sigma0(a).wrapping_add(maj(a, b, c));
164	
165	                    h = g;
166	                    g = f;
167	                    f = e;
168	                    e = d.wrapping_add(t1);
169	                    d = c;
170	                    c = b;
171	                    b = a;
172	                    a = t1.wrapping_add(t2);
173	
174	                    i += 1;
175	                }
176	
177	                state[0] = state[0].wrapping_add(a);
178	                state[1] = state[1].wrapping_add(b);
179	                state[2] = state[2].wrapping_add(c);
180	                state[3] = state[3].wrapping_add(d);
181	                state[4] = state[4].wrapping_add(e);
182	                state[5] = state[5].wrapping_add(f);
183	                state[6] = state[6].wrapping_add(g);
184	                state[7] = state[7].wrapping_add(h);
185	
186	                state
187	            }
188	        }
189	    };
190	}
191	
